#!/usr/bin/env python3
"""Fail-closed classifier for shared /app worktree runtime artifacts."""
from __future__ import annotations

import argparse
import json
import subprocess
from pathlib import Path
from typing import Any

RUNTIME_RECOVERY_PREFIX = ("worker_queue", "triggers", "runtime-recovery")
ALLOWED_SUFFIXES = {".json", ".trigger"}
ALLOWED_SCHEMAS = {
    "edarsahub.runtime-recovery-trigger.v1",
    "edarsahub.worker-runtime-recovery-trigger.v1",
}
ALLOWED_KEYS = {
    "schema",
    "reason",
    "production_touched",
    "production_allowed",
    "existing_job_id",
    "target_job_id",
    "requested_by",
    "target_queue_branch",
    "queue_head_observed",
}
MAX_RUNTIME_ARTIFACT_BYTES = 64 * 1024


class RuntimeWorktreeGuardError(RuntimeError):
    pass


def _git_paths(repo: Path, *args: str) -> list[str]:
    proc = subprocess.run(
        ["git", *args],
        cwd=str(repo),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        check=False,
    )
    if proc.returncode != 0:
        raise RuntimeWorktreeGuardError(
            f"GIT_STATUS_FAILED:{' '.join(args)}:{proc.stderr.decode('utf-8', errors='replace')[-800:]}"
        )
    return [
        raw.decode("utf-8", errors="surrogateescape")
        for raw in proc.stdout.split(b"\0")
        if raw
    ]


def validate_runtime_artifact(repo: Path, relative: str) -> tuple[bool, str]:
    rel = Path(relative)
    if rel.is_absolute() or ".." in rel.parts:
        return False, "UNSAFE_PATH"
    if tuple(rel.parts[:3]) != RUNTIME_RECOVERY_PREFIX or len(rel.parts) != 4:
        return False, "PATH_NOT_ALLOWLISTED"
    if rel.suffix.lower() not in ALLOWED_SUFFIXES:
        return False, "SUFFIX_NOT_ALLOWLISTED"

    target = repo / rel
    if target.is_symlink():
        return False, "SYMLINK_FORBIDDEN"
    if not target.is_file():
        return False, "REGULAR_FILE_REQUIRED"

    try:
        size = target.stat().st_size
    except OSError:
        return False, "STAT_FAILED"
    if size <= 0 or size > MAX_RUNTIME_ARTIFACT_BYTES:
        return False, "SIZE_OUT_OF_RANGE"

    try:
        payload = json.loads(target.read_text(encoding="utf-8"))
    except Exception:
        return False, "INVALID_JSON"
    if not isinstance(payload, dict):
        return False, "JSON_OBJECT_REQUIRED"
    if payload.get("schema") not in ALLOWED_SCHEMAS:
        return False, "SCHEMA_NOT_ALLOWLISTED"
    if set(payload) - ALLOWED_KEYS:
        return False, "UNEXPECTED_FIELDS"
    if payload.get("production_touched") is not False:
        return False, "PRODUCTION_TOUCHED_MUST_BE_FALSE"
    if "production_allowed" in payload and payload.get("production_allowed") is not False:
        return False, "PRODUCTION_ALLOWED_MUST_BE_FALSE"
    if "target_queue_branch" in payload and payload.get("target_queue_branch") != "worker/requests":
        return False, "TARGET_QUEUE_BRANCH_NOT_ALLOWED"
    reason = payload.get("reason")
    if not isinstance(reason, str) or not reason.strip() or len(reason) > 4096:
        return False, "REASON_REQUIRED"
    for key in ("existing_job_id", "target_job_id", "requested_by", "queue_head_observed"):
        if key in payload and (not isinstance(payload[key], str) or len(payload[key]) > 200):
            return False, f"INVALID_{key.upper()}"
    return True, "VALIDATED_RUNTIME_ARTIFACT"


def classify_worktree(repo: Path) -> dict[str, Any]:
    repo = repo.resolve()
    staged = sorted(set(_git_paths(repo, "diff", "--cached", "--name-only", "-z")))
    unstaged = sorted(set(_git_paths(repo, "diff", "--name-only", "-z")))
    untracked = sorted(set(_git_paths(repo, "ls-files", "--others", "--exclude-standard", "-z")))

    validated: list[str] = []
    unsafe: list[dict[str, str]] = []
    for relative in untracked:
        ok, reason = validate_runtime_artifact(repo, relative)
        if ok:
            validated.append(relative)
        else:
            unsafe.append({"path": relative, "reason": reason})

    real_dirty = bool(staged or unstaged or unsafe)
    return {
        "worktree_dirty": real_dirty,
        "real_dirty": real_dirty,
        "staged_count": len(staged),
        "unstaged_count": len(unstaged),
        "untracked_count": len(untracked),
        "validated_runtime_artifact_count": len(validated),
        "unsafe_untracked_count": len(unsafe),
        "staged_paths": staged,
        "unstaged_paths": unstaged,
        "untracked_paths": untracked,
        "validated_runtime_artifacts": validated,
        "unsafe_untracked": unsafe,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--repo", default="/app")
    parser.add_argument("--json", action="store_true")
    parser.add_argument("--shell", action="store_true")
    parser.add_argument("--require-clean", action="store_true")
    args = parser.parse_args()

    try:
        state = classify_worktree(Path(args.repo))
    except Exception as exc:
        if args.json:
            print(json.dumps({"error": str(exc), "real_dirty": True}, sort_keys=True))
        else:
            print(f"RUNTIME_WORKTREE_GUARD_ERROR={exc}")
        return 75

    if args.json:
        print(json.dumps(state, ensure_ascii=False, sort_keys=True))
    if args.shell:
        print(f"STAGED_COUNT={state['staged_count']}")
        print(f"UNSTAGED_COUNT={state['unstaged_count']}")
        print(f"UNTRACKED_COUNT={state['untracked_count']}")
        print(f"VALIDATED_RUNTIME_ARTIFACT_COUNT={state['validated_runtime_artifact_count']}")
        print(f"UNSAFE_UNTRACKED_COUNT={state['unsafe_untracked_count']}")

    if args.require_clean and state["real_dirty"]:
        return 74
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

